INSERT INTO `ai_settings` VALUES (1,'lstm_units','64','int','lstm','LSTM Units','Number of units in the LSTM layer. Higher = more capacity but slower training.','2026-07-15 18:29:17','2026-07-17 11:11:26'),(2,'dropout_rate','0.1','float','lstm','Dropout Rate','Fraction of units randomly dropped during training (0.0–0.5). Prevents overfitting.','2026-07-15 18:29:17','2026-07-17 11:11:26'),(3,'l2_regularization','0.00001','float','lstm','L2 Regularization','L2 kernel/recurrent regularizer strength. Penalises large weights.','2026-07-15 18:29:17','2026-07-17 11:11:26'),(4,'sequence_window','7','int','lstm','Sequence Window (days)','Number of past days used as input to predict the next day.','2026-07-15 18:29:17','2026-07-17 11:11:26'),(5,'epochs','150','int','lstm','Max Training Epochs','Maximum number of training iterations. Early stopping may stop before this.','2026-07-15 18:29:17','2026-07-17 11:11:26'),(6,'batch_size','16','int','lstm','Batch Size','Number of samples processed per gradient update. Smaller = slower but often better.','2026-07-15 18:29:17','2026-07-17 11:11:26'),(7,'validation_split','0.15','float','lstm','Validation Split','Fraction of training data held out to monitor overfitting (0.05–0.30).','2026-07-15 18:29:17','2026-07-17 11:11:26'),(8,'early_stop_patience','10','int','lstm','Early Stop Patience','Epochs with no improvement before training stops early.','2026-07-15 18:29:17','2026-07-17 11:11:26'),(9,'min_data_points','45','int','lstm','Minimum Data Points','Minimum historical records required to run LSTM training.','2026-07-15 18:29:17','2026-07-17 11:11:26'),(10,'history_days','730','int','lstm','History Lookback (days)','How many days of historical data to include when building the training dataset.','2026-07-15 18:29:17','2026-07-17 11:11:26'),(11,'confidence_min','0.30','float','lstm','Confidence Score Floor','Minimum allowed confidence score returned to the UI (0.0–1.0).','2026-07-15 18:29:17','2026-07-17 11:11:26'),(12,'confidence_max','0.92','float','lstm','Confidence Score Ceiling','Maximum allowed confidence score returned to the UI (0.0–1.0).','2026-07-15 18:29:17','2026-07-17 11:11:26'),(13,'ma_window','7','int','fallback','MA Window Size','Moving average window (days) used when the LSTM service is unavailable.','2026-07-15 18:29:17','2026-07-17 11:11:26'),(14,'ma_weekend_factor','0.9','float','fallback','Weekend Demand Factor','Multiplier applied to weekend day predictions in the fallback model.','2026-07-15 18:29:17','2026-07-17 11:11:26'),(15,'ma_lower_bound','0.8','float','fallback','Lower Bound Multiplier','Prediction × this value = lower confidence bound in fallback forecasts.','2026-07-15 18:29:17','2026-07-17 11:11:26'),(16,'ma_upper_bound','1.2','float','fallback','Upper Bound Multiplier','Prediction × this value = upper confidence bound in fallback forecasts.','2026-07-15 18:29:17','2026-07-17 11:11:26'),(17,'ma_confidence','0.60','float','fallback','Fallback Confidence Score','Fixed confidence score assigned to all fallback (non-LSTM) predictions.','2026-07-15 18:29:17','2026-07-17 11:11:26'),(18,'urgency_hours','24','int','decision','Urgency Threshold (hours)','Bookings created within this many hours of their start time are flagged as urgent.','2026-07-15 18:29:17','2026-07-17 11:11:26'),(19,'long_duration_hours','4','int','decision','Long Duration Threshold (hours)','Bookings longer than this duration receive an additional risk score.','2026-07-15 18:29:17','2026-07-17 11:11:26'),(20,'risk_high_threshold','70','int','decision','High Risk Score Threshold','Risk scores at or above this value are labelled High Risk.','2026-07-15 18:29:17','2026-07-17 11:11:26'),(21,'risk_med_threshold','40','int','decision','Medium Risk Score Threshold','Risk scores at or above this value (and below High) are labelled Medium Risk.','2026-07-15 18:29:17','2026-07-17 11:11:26'),(22,'conflict_score_peak_hour','30','int','decision','Score: Peak Hour','Points added when the booking falls in a peak usage hour.','2026-07-15 18:29:17','2026-07-17 11:11:26'),(23,'conflict_score_high_day_vol','20','int','decision','Score: High Day Volume','Points added when the requested day has above-average booking volume.','2026-07-15 18:29:17','2026-07-17 11:11:26'),(24,'conflict_score_short_notice','25','int','decision','Score: Short Notice','Points added for bookings made within the urgency window.','2026-07-15 18:29:17','2026-07-17 11:11:26'),(25,'conflict_score_long_duration','15','int','decision','Score: Long Duration','Points added for bookings exceeding the long-duration threshold.','2026-07-15 18:29:17','2026-07-17 11:11:26'),(26,'conflict_score_popular_room','10','int','decision','Score: Popular Room','Points added when a frequently-booked room is requested.','2026-07-15 18:29:17','2026-07-17 11:11:26'),(27,'conflict_day_volume_ratio','1.2','float','decision','Day Volume Ratio','A day is considered high-volume when its count exceeds average × this ratio.','2026-07-15 18:29:17','2026-07-17 11:11:26'),(28,'demand_spike_multiplier','1.5','float','decision','Demand Spike Multiplier','Recent frequency must exceed average × this value to trigger a spike alert.','2026-07-15 18:29:17','2026-07-17 11:11:26'),(29,'low_approval_threshold','60','float','decision','Low Approval Rate Threshold (%)','Approval rates below this percentage trigger a low-approval-rate anomaly.','2026-07-15 18:29:17','2026-07-17 11:11:26'),(30,'approval_improvement_threshold','70','float','decision','Approval Improvement Threshold (%)','Approval rates below this generate a process-improvement recommendation.','2026-07-15 18:29:17','2026-07-17 11:11:26'),(31,'ma_noise_factor','0.1','float','fallback','MA Noise Factor','Random noise injected into occupancy fallback predictions (fraction of average).','2026-07-15 18:29:17','2026-07-17 11:11:26'),(32,'ma_floor_avg','3.0','float','fallback','MA Floor Average','Minimum average used in occupancy fallback when no history exists.','2026-07-15 18:29:17','2026-07-17 11:11:26'),(33,'spam_threshold','10','int','security','Form Spam Threshold','Number of form submissions from the same IP within the window before flagging spam.','2026-07-15 18:29:17','2026-07-17 11:11:26'),(34,'spam_window_seconds','60','int','security','Spam Detection Window (seconds)','Time window in seconds for the form spam rate-limiter.','2026-07-15 18:29:17','2026-07-17 11:11:26'),(35,'priority_admin','1.0','float','decision','Priority Multiplier: Admin','Risk score multiplier applied to bookings made by Admin role users.','2026-07-15 18:29:17','2026-07-17 11:11:26'),(36,'priority_manager','0.8','float','decision','Priority Multiplier: Manager','Risk score multiplier applied to bookings made by Manager role users.','2026-07-15 18:29:17','2026-07-17 11:11:26'),(37,'priority_default','0.5','float','decision','Priority Multiplier: Default','Risk score multiplier applied to all other role users.','2026-07-15 18:29:17','2026-07-17 11:11:26');
/*!40000 ALTER TABLE `ai_settings` ENABLE KEYS */;
